SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.ar.root.articles"."articles" AS "articles", "_root.ar.root.page"."page" AS "page"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')   ORDER BY "id" ASC NULLS LAST LIMIT 4 OFFSET 1) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("page" ORDER BY "root.ar.root.page.pg.id" DESC NULLS FIRST), '[]' ) AS "page" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.page.base"."id" AS "id"       ) AS "_e"      ) ) AS "page", "_root.ar.root.page.base"."id" AS "root.ar.root.page.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE (("_root.base"."id") = ("author_id"))   ORDER BY "id" DESC NULLS FIRST LIMIT 1 OFFSET 1) AS "_root.ar.root.page.base"    ORDER BY "root.ar.root.page.pg.id" DESC NULLS FIRST  ) AS "_root.ar.root.page"      ) AS "_root.ar.root.page" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("articles" ORDER BY "root.ar.root.articles.pg.id" ASC NULLS LAST), '[]' ) AS "articles" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.base"."id" AS "id"       ) AS "_e"      ) ) AS "articles", "_root.ar.root.articles.base"."id" AS "root.ar.root.articles.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE (("_root.base"."id") = ("author_id"))   ORDER BY "id" ASC NULLS LAST  OFFSET 1) AS "_root.ar.root.articles.base"    ORDER BY "root.ar.root.articles.pg.id" ASC NULLS LAST  ) AS "_root.ar.root.articles"      ) AS "_root.ar.root.articles" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
